class LiveCounter{constructor(targetValue,duration=2000,element=null){this.targetValue=targetValue;this.currentValue=0;this.duration=duration;this.element=element;this.animationId=null;this.startTime=null;this.isRunning=false;}easeOutExpo(t){return t===1 ? 1 : 1-Math.pow(2,-10*t);}start(){if(this.isRunning)return;this.isRunning=true;this.startTime=performance.now();this.animate();}animate(){const currentTime=performance.now();const elapsed=currentTime-this.startTime;const progress=Math.min(elapsed/this.duration,1);const easedProgress=this.easeOutExpo(progress);this.currentValue=Math.floor(easedProgress*this.targetValue);if(this.element){this.element.textContent=this.currentValue.toLocaleString();}if(progress<1){this.animationId=requestAnimationFrame(()=>this.animate());}else{this.isRunning=false;this.currentValue=this.targetValue;if(this.element){this.element.textContent=this.targetValue.toLocaleString();}}}stop(){if(this.animationId){cancelAnimationFrame(this.animationId);this.animationId=null;}this.isRunning=false;}update(newTargetValue){this.stop();this.targetValue=newTargetValue;this.currentValue=0;this.start();}getCurrentValue(){return this.currentValue;}addPulseAnimation(){if(this.element){this.element.classList.add('pulse-active');setTimeout(()=>{this.element.classList.remove('pulse-active');},1000);}}}function initializeLiveCounters(){const counterElements=document.querySelectorAll('[data-counter]');counterElements.forEach(element=>{const targetValue=parseInt(element.dataset.counter,10);const duration=parseInt(element.dataset.duration||2000,10);const counter=new LiveCounter(targetValue,duration,element);const observer=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting&&!counter.isRunning){counter.start();if(element.dataset.pulse==='true'){counter.addPulseAnimation();}}});},{threshold: 0.5});observer.observe(element);});}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initializeLiveCounters);}else{initializeLiveCounters();}